contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public function testing approve behaviour
    function run(address spender, uint256 value) public payable {
        require(spender != address(0));

        bool reverted;
        c.approve(spender, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 observed = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        // If the call did not revert then the allowance must equal the requested value.
        assert(reverted || observed == value);
    }

    receive() external payable {}
}

